create or replace function private.dashboard_attention_summary() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin return jsonb_build_object('csrDue',case when public.has_permission_for_current_user('view_csr') then (select count(*) from public.post_job_followups where status='pending' and due_at<=now()) else 0 end,'estimateFollowups',case when public.has_permission_for_current_user('view_estimates') then (select count(*) from public.estimates where status in ('draft','sent') and follow_up_at is not null and follow_up_at<=now()) else 0 end,'renewals30',case when public.has_permission_for_current_user('view_customers') then (select count(*) from public.service_agreements where status='active' and renewal_date is not null and renewal_date<=current_date+30) else 0 end,'pastDueInvoices',case when public.has_permission_for_current_user('view_billing') then (select count(*) from public.invoices where status='open' and due_at is not null and due_at<now()) else 0 end,'openAr',case when public.has_permission_for_current_user('view_billing') then (select coalesce(sum(greatest(i.total-coalesce((select sum(p.amount) from public.payments p where p.invoice_id=i.id),0),0)),0) from public.invoices i where i.status='open') else 0 end,'openOpportunities',case when public.has_permission_for_current_user('view_estimates') then (select count(*) from public.sales_opportunities where stage not in ('won','lost','closed')) else 0 end); end $$; create or replace function public.dashboard_attention_summary() returns jsonb language sql stable set search_path='' as $$ select private.dashboard_attention_summary() $$; revoke all on function public.dashboard_attention_summary() from public,anon; grant execute on function public.dashboard_attention_summary() to authenticated;